<script lang="ts">
 import {refreshAll} from '$app/navigation';
 import {numberingScopes,numberingDate,formatNumber,validateNumberTemplate} from '@schubert/domain';
 import {command,request} from '#lib/client/api.ts';
 import type {AppData,Row} from '#lib/client/types.ts';
 import Icon from './Icon.svelte';
 let {data}:{data:AppData}=$props();
 let scope=$state('invoices'),template=$state(''),padding=$state(5),annual=$state(true),next=$state(1),reason=$state(''),password=$state(''),busy=$state(false),error=$state(''),notice=$state('');
 const profiles=$derived(data.related.numbering_profiles??[]),counters=$derived(data.related.number_counters??[]),date=numberingDate();
 const selected=$derived(numberingScopes.find(s=>s.scope===scope)!);
 const profile=$derived(profiles.find((p:Row)=>p.scope===scope));
 const counter=$derived(counters.find((c:Row)=>c.scope===scope&&Number(c.year)===(annual?date.year:0)));
 $effect(()=>{const p=profiles.find((p:Row)=>p.scope===scope),item=numberingScopes.find(s=>s.scope===scope)!;template=p?.template??(scope==='invoices'?(data.settings.invoice_prefix??item.prefix):item.prefix)+'-{JJJJ}-{NR}';padding=Number(p?.padding??5);annual=p?.annual??true;next=Number(counters.find((c:Row)=>c.scope===scope&&Number(c.year)===(p?.annual===false?0:date.year))?.last_value??0)+1;error='';notice='';reason='';password='';});
 const preview=$derived.by(()=>{try{validateNumberTemplate(template,Number(padding),annual);return {text:formatNumber(template,Number(padding),Number(next),date),error:''};}catch(cause){return {text:'Vorschau nach vollständiger Eingabe',error:(cause as Error).message};}});
 async function save(event:SubmitEvent){event.preventDefault();if(busy||preview.error)return;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});const result=await command('settings.numbering.update',undefined,{scope,template,padding:Number(padding),annual,next:Number(next),reason},profile?.version);await refreshAll();password='';notice='Nummernkreis gespeichert. Die nächste Vergabe lautet '+result.preview+'. Bestehende Nummern bleiben unverändert.';}catch(cause){error=cause instanceof Error?cause.message:'Nummernkreis konnte nicht gespeichert werden.';}finally{busy=false;}}
</script>
<section class="panel" aria-labelledby="numbering-title"><header class="panel-header"><div><h2 id="numbering-title">Ihre Nummernkreise</h2><p>Aufbau und nächsten freien Stand für den Umstieg festlegen.</p></div></header>
 <form onsubmit={save}><fieldset class="panel-body numbering-fields" disabled={busy}>
  <div class="field"><label for="numbering-scope">Welche Nummer möchten Sie einstellen?</label><select id="numbering-scope" bind:value={scope}>{#each numberingScopes as item}<option value={item.scope}>{item.label}</option>{/each}</select></div>
  <div class="numbering-preview" aria-live="polite"><span>Nächste Nummer für {selected.label}</span><strong>{preview.text}</strong><p>{scope==='invoices'?'Wird erst bei der verbindlichen Rechnungsausstellung vergeben.':'Wird beim nächsten entsprechenden Vorgang vergeben.'} Die Vorschau reserviert noch keine Nummer.</p></div>
  <div class="field-grid"><div class="field full"><label for="numbering-template">Aufbau der Nummer *</label><input id="numbering-template" bind:value={template} maxlength="80" required aria-describedby="numbering-template-help"/><span class="field-help" id="numbering-template-help">{'{NR}'} = laufende Nummer · {'{JJJJ}'} = Jahr mit vier Stellen · {'{JJ}'} = Jahr mit zwei Stellen · {'{MM}'} = Monat. Beispiel: {'RE-{JJJJ}-{NR}'}.</span></div>
  <div class="field"><label for="numbering-padding">Mindeststellen der laufenden Nummer *</label><input id="numbering-padding" type="number" min="1" max="10" step="1" bind:value={padding} required/><span class="field-help">Bei 5 Stellen wird aus 42 die Zahl 00042. Größere Nummern werden vollständig ausgegeben.</span></div>
  <div class="field"><label for="numbering-reset">Zählweise *</label><select id="numbering-reset" bind:value={annual}><option value={true}>Jährlich neu · ab 1 im Folgejahr</option><option value={false}>Fortlaufend über alle Jahre</option></select><span class="field-help">Jahr und Monat richten sich nach Europe/Berlin. Bei jährlicher Zählung muss das Jahr im Aufbau enthalten sein.</span></div>
  <div class="field full"><label for="numbering-next">Nächste freie Nummer {annual?'für '+date.year:''} *</label><input id="numbering-next" type="number" min={Number(counter?.last_value??0)+1} max="2147483647" step="1" bind:value={next} required/><span class="field-help">Wenn Ihre letzte Nummer im bisherigen System 347 war, tragen Sie 348 ein. In dieser Suite bereits verbrauchter Stand: {counter?.last_value??0}. Zurücksetzen und doppelte Nummern werden verhindert.</span></div>
  <div class="field full"><label for="numbering-reason">Grund und Grundlage des Startstands *</label><textarea id="numbering-reason" bind:value={reason} required minlength="8" maxlength="1000" placeholder="Zum Beispiel: Umstieg am 18.10.; letzte Nummer im bisherigen System: RE-2026-00347"></textarea></div>
  <div class="field full"><label for="numbering-password">Eigene Passphrase bestätigen *</label><input id="numbering-password" type="password" autocomplete="current-password" bind:value={password} required/><span class="field-help">Schützt die Änderung der betrieblichen Nummernvergabe.</span></div></div>
  {#if preview.error}<p class="field-error mt" role="status">{preview.error}</p>{/if}{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}{#if notice}<p class="field-help mt" role="status">{notice}</p>{/if}
 </fieldset><footer class="panel-footer"><span class="small muted">Gilt für neue Vergaben. Bestehende Belege bleiben unverändert.</span><button class="btn primary" disabled={busy||!!preview.error}><Icon name={busy?'refresh':'check'} size={15}/>{busy?'Wird gespeichert …':'Nummernkreis speichern'}</button></footer></form>
</section>
<style>.numbering-fields{border:0;margin:0;min-width:0}.numbering-fields>.field{max-width:560px}.numbering-preview{margin:24px 0 28px;padding:24px;background:var(--wash);border-radius:12px}.numbering-preview>span{font-size:13px;color:var(--muted)}.numbering-preview strong{display:block;font-size:26px;line-height:1.4;font-variant-numeric:tabular-nums;letter-spacing:-.02em;overflow-wrap:anywhere;margin:10px 0}.numbering-preview p{max-width:65ch;font-size:13px;line-height:1.7}.panel-footer{flex-wrap:wrap;gap:16px}@media(max-width:760px){.numbering-preview{padding:20px}.numbering-preview strong{font-size:23px}}</style>
